public int FindMaximumXOR(int[] nums) {
    int best = 0;
    var prefixes = new HashSet<int>();
    for (int k = 30; k >= 0; k--) {             // nums[i] < 2^31: bits 30..0
        prefixes.Clear();
        foreach (int v in nums) prefixes.Add(v >> k);
        int cand = (best << 1) | 1;             // we want a 1 in bit k
        best <<= 1;
        foreach (int p in prefixes)
            if (prefixes.Contains(p ^ cand)) { best = cand; break; }   // a pair p, p ^ cand exists
    }
    return best;
}

