int node = 0, best = 0;
for (int k = Top; k >= 0; k--) {
    int want = ((x >> k) & 1) ^ 1;          // the opposite bit makes a 1 in x ^ y
    int cand = (node << 1) | want;
    if (levels[k].Contains(cand)) { node = cand; best |= 1 << k; }
    else node = cand ^ 1;                   // forced: some number goes this way
}

