void ForEachPiece(ulong b) {
    while (b != 0) {
        int sq = math.tzcnt(b);                      // the lowest piece's cell; .NET: BitOperations.TrailingZeroCount
        int x = sq & 7, y = sq >> 3;
        b &= b - 1;                                  // Kernighan: remove it
    }
}

